const CACHE='sams-canvas-v23';
const ASSETS=['./','./index.html','./style.css?v=21','./editor.js?v=20','./gestures.js?v=20','./app.js?v=22','./updater.js?v=2','./content.js?v=21','./view-session.js?v=20','./welcome.js?v=20','./calendar.js?v=20','./projects.js?v=20','./canvas-tools.js?v=20','./studio.js?v=20','./studio.css?v=23','./knife-cursor.svg','./pen-cursor.svg','./audio/birds.ogg','./audio/wind.ogg','./audio/stream.ogg','./audio/rain.ogg','./icon.svg','./icon-192.png','./icon-256.png','./icon-512.png','./logo.png','./manifest.webmanifest','./cozy-world.svg','./cloud-config.json'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));self.skipWaiting()});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim()});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});
